// Small compatibility adapter over the bundled pdf-lib runtime.
window.jspdf={jsPDF:class{
 constructor(){this.pages=[[]];this.fontSize=10;this.bold=false;this.color=[37,45,51];this.draw=[150,150,150];this.fill=[237,112,91]}
 setFont(_,style){this.bold=style.includes('bold');this.italic=style.includes('italic')} setFontSize(n){this.fontSize=n}setTextColor(...v){this.color=v}setDrawColor(...v){this.draw=v}setFillColor(...v){this.fill=v}
 addPage(){this.pages.push([])}push(v){this.pages.at(-1).push(v)}
 async initializeFonts(family){const {PDFDocument,StandardFonts}=window.PDFLib;this.doc=await PDFDocument.create();const pair=({helvetica:[StandardFonts.Helvetica,StandardFonts.HelveticaBold],times:[StandardFonts.TimesRoman,StandardFonts.TimesRomanBold],courier:[StandardFonts.Courier,StandardFonts.CourierBold]})[family]||[StandardFonts.Helvetica,StandardFonts.HelveticaBold];this.normal=await this.doc.embedFont(pair[0]);this.boldFont=await this.doc.embedFont(pair[1]);const extra=({helvetica:[StandardFonts.HelveticaOblique,StandardFonts.HelveticaBoldOblique],times:[StandardFonts.TimesRomanItalic,StandardFonts.TimesRomanBoldItalic],courier:[StandardFonts.CourierOblique,StandardFonts.CourierBoldOblique]})[family]||[StandardFonts.HelveticaOblique,StandardFonts.HelveticaBoldOblique];this.italicFont=await this.doc.embedFont(extra[0]);this.boldItalicFont=await this.doc.embedFont(extra[1])}
 splitTextToSize(text,width){const font=this.currentFont(),limit=width*2.83465;return String(text).split('\n').flatMap(paragraph=>{const out=[];let line='';for(const word of paragraph.split(/\s+/)){const candidate=line?(line+' '+word):word;if(font.widthOfTextAtSize(candidate,this.fontSize)<=limit){line=candidate;continue}if(line){out.push(line);line=''}let chunk='';for(const letter of word){if(chunk&&font.widthOfTextAtSize(chunk+letter,this.fontSize)>limit){out.push(chunk);chunk=''}chunk+=letter}line=chunk}out.push(line);return out})}
 currentFont(){return this.italic?(this.bold?this.boldItalicFont:this.italicFont):(this.bold?this.boldFont:this.normal)}
 textWidth(text){return this.currentFont().widthOfTextAtSize(text,this.fontSize)/2.83465}
 justifyLine(text,x,y,width){const words=text.split(/\s+/);if(words.length<2){this.text(text,x,y);return}const total=words.reduce((sum,word)=>sum+this.textWidth(word),0);const gap=(width-total)/(words.length-1);if(gap<0){this.text(text,x,y);return}for(const word of words){this.text(word,x,y);x+=this.textWidth(word)+gap}}
 text(text,x,y,options={}){const w=this.textWidth(text);x-=options.align==='center'?w/2:options.align==='right'?w:0;this.push({type:'text',text,x,y,size:this.fontSize,bold:this.bold,italic:this.italic,color:this.color})}line(x,y,x2,y2){this.push({type:'line',x,y,x2,y2,color:this.draw})}rect(x,y,w,h){this.push({type:'rect',x,y,w,h,color:this.fill})}addImage(image,_,x,y,w,h){this.push({type:'image',image,x,y,w,h})}
 async save(name){const {PDFDocument,StandardFonts,rgb}=window.PDFLib,doc=this.doc,normal=this.normal,bold=this.boldFont,mm=2.83465;for(const commands of this.pages){const page=doc.addPage([210*mm,297*mm]);for(const c of commands){const color=c.color?rgb(...c.color.map(n=>n/255)):null;if(c.type==='text')page.drawText(c.text,{x:c.x*mm,y:(297-c.y)*mm,size:c.size,font:c.italic?(c.bold?this.boldItalicFont:this.italicFont):(c.bold?bold:normal),color});if(c.type==='line')page.drawLine({start:{x:c.x*mm,y:(297-c.y)*mm},end:{x:c.x2*mm,y:(297-c.y2)*mm},thickness:.5,color});if(c.type==='rect')page.drawRectangle({x:c.x*mm,y:(297-c.y-c.h)*mm,width:c.w*mm,height:c.h*mm,color});if(c.type==='image')page.drawImage(await doc.embedJpg(c.image),{x:c.x*mm,y:(297-c.y-c.h)*mm,width:c.w*mm,height:c.h*mm})}}const url=URL.createObjectURL(new Blob([await doc.save()],{type:'application/pdf'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000)}
}};
